package com.kiwiplan.mes;

import java.util.Date;

public class ShipmentScheduler {
    public Date dueDate(int year, int month, int day) {
        // Date(year-1900, month-0-based, day) is deprecated.
        return new Date(year - 1900, month - 1, day);
    }

    public Integer priorityBox(int p) {
        return new Integer(p); // deprecated boxing constructor
    }

    public void runReport(String cmd) throws Exception {
        Runtime.getRuntime().exec(cmd); // deprecated String overload
    }
}
